                    settimer "NoTargetTimer" 0
                    attack ClosestTarget
                elseif find ClosestTarget ground -1 -1 TargetAttackRange and not dead ClosestTarget
                    overhead " ▼ " 253 ClosestTarget
                    settimer "TargetAcquired" 0
                    settimer "NoTargetTimer" 0
