                    if EnableOverheadMessages != 0
                        overhead "*working on chest...*" 1182
                    endif

                    if not hidden and not cooldown "Hiding" and timer "StealthCheck > 10500
                        useskill "Hiding"
                    endif

                    settimer "ChestRadar" 0

                    while gumpexists 736038070
                        if not hidden and not cooldown "Hiding" and timer "StealthCheck" > 10500
                            useskill "Hiding"
                        endif

                        if insysmsg "successfully cleared it of traps"
                            if EnableOverheadMessages != 0
                                overhead "*screech*" 2114 TargetDungeonChest
                            endif
                            if EnableOverheadMessages = 1
                                overhead "There!  That should disable the traps..." 2086
                            endif
                            settimer "ChestRadar" 0
                            clearsysmsg
                            wait 500
                            @setvar! TimetoPick 1
                            if findtype "lockpicks" backpack as Lockpicks and TimetoPick = 1
                                gumpresponse 4 736038070
                            else
                                if EnableOverheadMessages = 1
                                    overhead "I am out of lockpicks!" 2086
                                elseif EnableOverheadMessages = 2
                                    overhead "[ NO LOCKPICKS! ]" 337
                                endif
                            endif
                        endif

                        if NeedtoRemoveTrap = 1
                            if findtype "drill" backpack as RemoveTrapTool
                                gumpresponse 7 736038070
                                wait 250
                                if insysmsg "You do not have any trap tools of that material"
                                    gumpresponse 5 736038070
                                endif
                                @setvar! NeedtoRemoveTrap 0
                            else
                                if EnableOverheadMessages = 1
                                    overhead "I am out of trap removal tools!" 2086
                                elseif EnableOverheadMessages = 2
                                    overhead "[ NO TRAP TOOLS! ]" 337
                                endif
                                replay
                            endif
                        endif

                        if insysmsg "successfully pick the lock"
                            if EnableOverheadMessages != 0
                                overhead "*click*" 2117 TargetDungeonChest
                            endif
                            if EnableOverheadMessages = 1
                                overhead "Bingo!  That does it..." 2086
                            endif
                            settimer "ChestRadar" 0
                            wait 500
                            clearsysmsg
                            replay
                        endif
                        wait 500
                    endwhile
                    endfor
                else
                    if timer "NoTargetTimer" > 4000
                        if EnableOverheadMessages = 1
                            overhead "This one is already empty..." 2086
                        endif
                        settimer "NoTargetTimer" 0
                    endif
                endif
            endif
        endif

        wait 250

        while cooldown "Hiding"
            if warmode
                @setvar! TimeToGo 1
                replay
            endif

            if findtype "Elven SpellBlade" hand
                replay
            endif

            if timer "TargetTimer" > 2500 and EnableOverheadMessages != 0
                overhead "▌ WAIT... ▌" 253
                settimer "TargetTimer" 0
            endif

            if not hidden
                settimer HidingTimer 0
                replay
            endif

            if not cooldown "Hiding"
                settimer "TargetTimer" 0
                break
            endif
        endwhile

        wait 250

        while hidden and Stealthing = 0
            @setvar! ChestTarget 0
            wait 500

            if not hidden
                settimer HidingTimer 0
                replay
            endif

            if findtype "Elven SpellBlade" hand
                replay
            endif

            if EnableChestRadar = 1
                if timer "ChestRadar" >= 4500
                    if findtype 3651|3649|3648|3650|3708|2475 ground -1 -1 18 as DungeonChest
                        getlabel DungeonChest descChest
                        if "lock" in descChest
                            overhead "descChest" 69 DungeonChest
                            overhead "▼" 69 DungeonChest
                            settimer "ChestRadar" 0
                        else
                            overhead "▄" 34 DungeonChest
                            settimer "ChestRadar" 0
                        endif
                    endif
                endif
            endif

            if insysmsg "You feel comfortable enough"
                if EnableOverheadMessages != 0
                    overhead "▌ READY! ▌" 69
                endif
                settimer "TargetTimer" 0
                clearsysmsg
                while not insysmsg "You begin to move quietly."
                    if timer OrganizerTimer > 30000
                        hotkey "Organizer Agent-05"
                        settimer OrganizerTimer 0
                    endif

                    if not hidden
                        settimer HidingTimer 0
                        replay
                    endif

                    if warmode
                        @setvar! TimeToGo 1
                        replay
                    endif

                    if timer "TargetTimer" > 4000 and EnableOverheadMessages != 0
                        overhead "▌ . . .  ▌" 69
                        settimer "TargetTimer" 0
                    endif

                    if EnableSkinningMode = 1
                        if findtype "Elven SpellBlade" hand
                            @setvar! SkinningMode 1
                            break
                        endif
                    endif

                    if EnableChestRadar = 1
                        if timer "ChestRadar" >= 4500
                            if findtype 3651|3649|3648|3650|3708|2475 ground -1 -1 18 as DungeonChest
                                getlabel DungeonChest descChest
                                if "lock" in descChest
                                    overhead "descChest" 69 DungeonChest
                                    overhead "▼" 69 DungeonChest
                                    settimer "ChestRadar" 0
                                else
                                    overhead "▄" 34 DungeonChest
                                    settimer "ChestRadar" 0
                                endif
                            endif
                        endif
                    endif

                    if Stealthing = 1
                        wait 250
                        break
                    endif

                    if insysmsg "You begin to move quietly"
                        if EnableOverheadMessages != 0
                            overhead "▌ START ▌" 69
                        endif
                        settimer "StealthCheck" 0
                        settimer "TargetTimer" 0
                        @setvar! Stealthing 1
                        clearsysmsg
                        break
                    endif

                    if insysmsg "Now tracking"
                        replay
                    endif
                endwhile

                if insysmsg "You begin to move quietly"
                    @setvar! Stealthing 1
                    clearsysmsg
                    break
                endif
            endif
        endwhile

        if insysmsg "You begin to move quietly"
            @setvar! Stealthing 1
            clearsysmsg
            wait 500
        endif

        while Stealthing = 1
            if dead
                 replay
            endif

            if not hidden
                @setvar! Stealthing 0
                replay
            endif

            if timer OrganizerTimer > 30000
                hotkey "Organizer Agent-05"
                settimer OrganizerTimer 0
            endif

            if warmode
                @setvar! TimeToGo 1
                replay
            endif

            if findtype "Elven SpellBlade" hand
                replay
            endif

            if insysmsg "You will automatically stealth when out of steps."
                @setvar! KeepOnTruckin 1
                clearsysmsg
            elseif timer "StealthCheck" < 10500
                @setvar! KeepOnTruckin 0
            endif

            if insysmsg "You begin to move quietly"
                settimer "StealthCheck" 0
                cooldown "Stealth" 10500
                settimer "TargetTimer" 0
                @setvar! Stealthing 1
                clearsysmsg
            endif

            if insysmsg "You feel ready to continue stealthing."
                @setvar! KeepOnTruckin 1
                clearsysmsg
            endif

            if insysmsg "You have 1 stealth steps" or insysmsg "You have 0 stealth steps"
                if KeepOnTruckin = 1 or insysmsg "You feel ready to continue stealthing."
                    @setvar! KeepOnTruckin 0
                    if timer "TargetTimer" > 2500 and EnableOverheadMessages != 0
                        overhead "▌ KEEP GOING! ▌" 69
                        settimer "TargetTimer" 0
                    endif
                    clearsysmsg
                else
                    clearsysmsg
                    while timer "StealthCheck" < 10500
                        if timer "StealthTimer" > 500 and EnableOverheadMessages != 0
                            overhead "▌ SLOW... ▌" 149
                            settimer "StealthTimer" 0
                            settimer "TargetTimer" 0
                            clearsysmsg
                        endif

                        if not hidden
                            @setvar! Stealthing 0
                            replay
                        endif

                        if timer "StealthCheck" > 10500
                            break
                        endif

                        if insysmsg "You have 0 stealth steps remaining."
                            clearsysmsg
                            if KeepOnTruckin = 1 or insysmsg "You feel ready to continue stealthing."
                                @setvar! KeepOnTruckin 0

                                if timer "TargetTimer" > 2500 and EnableOverheadMessages != 0
                                    overhead "▌ KEEP GOING! ▌" 69
                                    settimer "TargetTimer" 0
                                endif
                            else
                                while timer "StealthCheck" < 10500
                                    if timer "StealthTimer" > 500 and EnableOverheadMessages != 0
                                        overhead "▌ STOP! ▌" 37
                                        settimer "StealthTimer" 0
                                        settimer "TargetTimer" 0
                                        clearsysmsg
                                    endif

                                    if insysmsg "You feel ready to continue stealthing" and EnableOverheadMessages != 0
                                        overhead "▌ READY! ▌" 69
                                        settimer "TargetTimer" 0
                                        wait 500
                                        clearsysmsg
                                        break
                                    endif

                                    if not hidden
                                        @setvar! Stealthing 0
                                        replay
                                    endif

                                    if timer "StealthCheck" > 10500
                                        break
                                    endif
                                endwhile
                            endif
                        endif

                        if EnableChestRadar = 1
                            if timer "ChestRadar" >= 4500
                                if findtype 3651|3649|3648|3650|3708|2475 ground -1 -1 18 as DungeonChest
                                    getlabel DungeonChest descChest
                                    if "lock" in descChest
                                        overhead "descChest" 69 DungeonChest
                                        overhead "▼" 69 DungeonChest
                                        settimer "ChestRadar" 0
                                    else
                                        overhead "▄" 34 DungeonChest
                                        settimer "ChestRadar" 0
                                    endif
                                endif
                            endif
                        endif
                    endwhile
                endif
            endif

            if insysmsg "You feel ready to continue stealthing" and EnableOverheadMessages != 0
                overhead "▌ READY! ▌" 69
                settimer "TargetTimer" 0
                wait 500
                clearsysmsg
            endif

            if timer "TargetTimer" > 4000 and not cooldown "Hiding" and timer "StealthCheck" > 10500 and EnableOverheadMessages != 0
                overhead "●" 69
                settimer "TargetTimer" 0
            endif

            if EnableSkinningMode = 1
                if findtype "Elven SpellBlade" hand
                    @setvar! SkinningMode 1
                    replay
                endif
            endif

            if EnableGoldVacuum = 1
                if findtype "gold coin" ground -1 -1 12 as droppedmoney and timer "GoldRadar" > 3500
                    if EnableOverheadMessages = 1
                        overhead "[ $ ]" 149 droppedmoney
                    endif
                    overhead "▼" 149 droppedmoney
                    settimer "GoldRadar" 0
                endif

                while findtype "gold coin" ground -1 -1 2 as finderskeepers
                    overhead " ▲ " 149
                    hotkey "Grab Item"
                    wft 2500
                    target finderskeepers
                    wait 500
                    if insysmsg "Invalid or inaccessible item"
                        wait 500
                        @ignore finderskeepers
                    endif
                    wait 500
                endwhile
            endif

            if EnableDungeonCleanup = 1
                if findtype "iron ingot%s|board%s|cut up leather|Ginseng|Garlic|Blood Moss|Sulfurous Ash|Mandrake Root%s%|Nightshade|Black Pearl%s%|Spider's Silk" ground -1 -1 18 as AnotherMansTreasure and timer "DungeonCleanupRadar" > 3500
                    # '
                    overhead "▼" 333 AnotherMansTreasure
                    settimer "DungeonCleanupRadar" 0
                endif

                while findtype "iron ingot%s|board%s|cut up leather|Ginseng|Garlic|Blood Moss|Sulfurous Ash|Mandrake Root%s%|Nightshade|Black Pearl%s%|Spider's Silk" ground -1 -1 2 as AnotherMansTreasure and timer "DungeonCleanupTimer" > 500
                    # '
                    if timer "InventoryTimer" > 3500 and EnableOverheadMessages = 1
                        overhead "[ CLEANUP... ]" 333
                        settimer "InventoryTimer" 0
                    endif
                    hotkey "Grab Item"
                    wft 2500
                    target AnotherMansTreasure
                    wait 500
                    if insysmsg "Invalid or inaccessible item"
                        if EnableOverheadMessages = 1
                            overhead "I can't get to that!" 2086
                            # '
                        endif
                        wait 500
                        @ignore AnotherMansTreasure
                    endif
                    settimer "DungeonCleanupTimer" 0
                endwhile
            endif

            if EnableChestRadar = 1
                if timer "ChestRadar" >= 4500
                    if findtype 3651|3649|3648|3650|3708|2475 ground -1 -1 18 as DungeonChest
                        getlabel DungeonChest descChest
                        if "lock" in descChest
                            overhead "descChest" 69 DungeonChest
                            overhead "▼" 69 DungeonChest
                            settimer "ChestRadar" 0
                        else
                            overhead "▄" 34 DungeonChest
                            settimer "ChestRadar" 0
                        endif
                    endif
                endif
            endif

            if findtype 3651|3649|3648|3650|3708|2475 ground -1 -1 2 as TargetDungeonChest and EnableAutoPickDungeonChests = 1
                getlabel TargetDungeonChest TargetDungeonChestdesc
                if "lock" in TargetDungeonChestdesc
                    dclick TargetDungeonChest
                    @setvar! ChestTarget TargetDungeonChest
                    wait 500
                    @setvar! TimetoPick 0
                    @setvar! NeedtoRemoveTrap 1

                    for 10
                    if EnableOverheadMessages != 0
                        overhead "*working on chest...*" 1182
                    endif

                    if not hidden and not cooldown "Hiding" and timer "StealthCheck" > 10500
                        useskill "Hiding"
                    endif

                    settimer "ChestRadar" 0

                    while gumpexists 736038070
                        if not hidden and not cooldown "Hiding" and timer "StealthCheck" > 10500
                            useskill "Hiding"
                        endif

                        if insysmsg "successfully cleared it of traps"
                            if EnableOverheadMessages != 0
                                overhead "*screech*" 2114 TargetDungeonChest
                            endif
                            if EnableOverheadMessages = 1
                                overhead "There!  That should disable the traps..." 2086
                            endif
                            settimer "ChestRadar" 0
                            clearsysmsg
                            wait 500
                            @setvar! TimetoPick 1
                            if findtype "lockpicks" backpack as Lockpicks and TimetoPick = 1
                                gumpresponse 4 736038070
                            else
                                if EnableOverheadMessages = 1
                                    overhead "I am out of lockpicks!" 2086
                                elseif EnableOverheadMessages = 2
                                    overhead "[ NO LOCKPICKS! ]" 337
                                endif
                            endif
                        endif

                        if NeedtoRemoveTrap = 1
                            if findtype "drill" backpack as RemoveTrapTool
                                gumpresponse 7 736038070
                                wait 250
                                if insysmsg "You do not have any trap tools of that material"
                                    gumpresponse 5 736038070
                                endif
                                @setvar! NeedtoRemoveTrap 0
                            else
                                if EnableOverheadMessages = 1
                                    overhead "I am out of trap removal tools!" 2086
                                elseif EnableOverheadMessages = 2
                                    overhead "[ NO TRAP TOOLS! ]" 337
                                endif
                                replay
                            endif
                        endif

                        if insysmsg "successfully pick the lock"
                            if EnableOverheadMessages != 0
                                overhead "*click*" 2117 TargetDungeonChest
                            endif

                            if EnableOverheadMessages = 1
                                overhead "Bingo!  That does it..." 2086
                            endif

                            settimer "ChestRadar" 0
                            wait 500
                            clearsysmsg
                            replay
                        endif
                        wait 500
                    endwhile
                    endfor
                else
                    if timer "TargetTimer" > 4000
                        if EnableOverheadMessages = 1
                            overhead "This one is already empty..." 2086
                        endif
                        settimer "TargetTimer" 0
                    endif
                endif
                @setvar! NeedtoSecureLoot 1
                replay
            endif
        endwhile
        replay
    endif
    replay
elseif dead
    if EnableOverheadMessages != 0
        overhead "[ R.I.P. ]" 337
    endif
    wait 1500
    settimer "TargetTimer" 0
    settimer "NoTargetTimer" 4000
    settimer "InventoryTimer" 0
    while dead
        @setvar! DEAD 1

        if EnableResetLoadoutAfterDeath = 1
            @setvar! ResetLoadout 1
        else
            @setvar! ResetLoadout 0
        endif
        wait 500

        if timer "NoTargetTimer" > 4000 and EnableOverheadMessages != 0
            overhead "[ FIND A HEALER! ]" 0
            settimer "NoTargetTimer" 0
        endif

        if findtype "blue moongate|30528|moongate" ground -1 -1 12 as EscapeGate and EnableOverheadMessages != 0
            if timer "TargetTimer" > 1000
                overhead " ▼ " 253 EscapeGate
                settimer "TargetTimer" 0
            endif
        endif

        while gumpexists 3773199800
            gumpresponse 16
            wait 500
            waitforgump 3773199800
            gumpresponse 2
            if EnableOverheadMessages = 1
                overhead "[ GATING TO TOWN... ]" 88
            endif
            break
        endwhile

        while gumpexists 2957810225
            if EnableOverheadMessages = 1
                overhead "[ HEALED! ]" 84
            endif
            gumpresponse 1
            wait 1000
            gumpclose 2957810225

            if EnableDressAfterRessurection = 1
                wait 1000
                if skill "Mining" >= 50 and EnableMining = 1
                    dress 'Miner'
                elseif skill "Lumberjacking" >= 50 and EnableLumberjacking = 1
                    dress 'Lumberjack'
                elseif skill "Fishing" >= 50 and EnableFishing = 1
                    dress 'Fisherman'
                elseif skill "Lockpicking" >= 50 and EnableDungeonPicker = 1
                    dress 'Scavenger'
                endif
                wait 500
                while queued
                    wait 100
                endwhile
                wait 1000
                if skill "Mining" >= 50 and EnableMining = 1
                    dress 'Miner'
                elseif skill "Lumberjacking" >= 50 and EnableLumberjacking = 1
                    dress 'Lumberjack'
                elseif skill "Fishing" >= 50 and EnableFishing = 1
                    dress 'Fisherman'
                elseif skill "Lockpicking" >= 50 and EnableDungeonPicker = 1
                    dress 'Scavenger'
                endif
            endif

            wait 500
            dclick backpack

            if EnableRecallAfterRessurection = 1
                @setvar! TimeToGo 1
                @setvar! ResThenTimeToGo 1
                wait 1000
                replay
            else
                wait 2500
                overhead "[ STOPPING SCRIPT ]" 84
                stop
            endif
        endwhile
    endwhile
endif
replay


