@clearignore
while findtype "gold coin" stackContainer as goldPile
 getlabel goldPile desc
 if ": 60000" in desc
     @ignore goldPile
 elseif ": 30000" in desc
     if stack30kPile == 0
         @setvar! stack30kPile goldPile
         @ignore goldPile
     else
         lift goldPile 30000
         drop stack30kPile
         @setvar! stack30kPile 0
         wait 750
     endif
 else
     lift goldPile 30000
     drop stackContainer
     wait 750
     getlabel goldPile desc
     if ": 30000" in desc
     elseif stackSmallPile == 0
         @setvar! stackSmallPile goldPile
         @ignore goldPile
     else
         lift goldPile 60000
         drop stackSmallPile
         @unignore stackSmallPile
         @setvar! stackSmallPile 0
         wait 750
     endif
 endif
endwhile

